using System.Collections;
using System.Collections.Generic;
using System.Linq;
using NUnit.Framework;
using Unity.FPS.AI;
using Unity.FPS.Game;
using Unity.FPS.Gameplay;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
using UnityEngine.SceneManagement;
using UnityEngine.TestTools;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace IronRequiem.Tests
{
    public sealed class PrimaryModuleTests
    {
        bool integrated,capsules;string Reports=>integrated?"Tools/IronRequiem/Reports/HitWeaponV04":capsules?"Tools/IronRequiem/Reports/PrimaryCapsules":"Tools/IronRequiem/Reports/PrimaryModuleV02";PlayerCharacterController player;PlayerWeaponsManager manager;Keyboard keyboard;Mouse mouse;UnityEngine.InputSystem.Utilities.ReadOnlyArray<InputDevice>? previous;float oldCapture;
        [UnitySetUp]public IEnumerator Setup(){integrated=TestContext.CurrentContext.Test.Name.StartsWith("Integrated");capsules=integrated||TestContext.CurrentContext.Test.Name.StartsWith("Capsules");Time.timeScale=1;oldCapture=Time.captureDeltaTime;Time.captureDeltaTime=1f/60;Application.runInBackground=true;previous=InputSystem.actions.devices;keyboard=InputSystem.AddDevice<Keyboard>();mouse=InputSystem.AddDevice<Mouse>();InputSystem.actions.devices=new InputDevice[]{keyboard,mouse};keyboard.MakeCurrent();mouse.MakeCurrent();EditorSceneManager.LoadSceneInPlayMode(integrated?"Assets/IronRequiem/Scenes/HitWeaponLab.unity":capsules?"Assets/IronRequiem/Scenes/PrimaryCapsulesLab.unity":"Assets/IronRequiem/Scenes/PrimaryModuleLab.unity",new LoadSceneParameters(LoadSceneMode.Single));yield return null;yield return null;player=Object.FindAnyObjectByType<PlayerCharacterController>();manager=player.GetComponent<PlayerWeaponsManager>();player.GetComponent<Health>().Invincible=true;foreach(var enemy in Object.FindObjectsByType<EnemyController>()){enemy.enabled=false;var mobile=enemy.GetComponent<EnemyMobile>();if(mobile)mobile.enabled=false;var big=enemy.GetComponent<BigBotCombat>();if(big)big.enabled=false;var turret=enemy.GetComponent<EnemyTurret>();if(turret)turret.enabled=false;enemy.NavMeshAgent.isStopped=true;}EditorWindow.GetWindow(typeof(EditorWindow).Assembly.GetType("UnityEditor.GameView")).Focus();Cursor.lockState=CursorLockMode.Locked;yield return new WaitForSeconds(.6f);}
        [UnityTearDown]public IEnumerator Cleanup(){Time.captureDeltaTime=oldCapture;Time.timeScale=1;var old=SceneManager.GetActiveScene();SceneManager.SetActiveScene(SceneManager.CreateScene("PrimaryCleanup"+Time.frameCount));yield return SceneManager.UnloadSceneAsync(old);InputSystem.actions.devices=previous;InputSystem.RemoveDevice(keyboard);InputSystem.RemoveDevice(mouse);Cursor.lockState=CursorLockMode.None;yield return null;}
        void Move(Vector3 position){var cc=player.GetComponent<CharacterController>();cc.enabled=false;player.transform.SetPositionAndRotation(position,Quaternion.identity);cc.enabled=true;player.CharacterVelocity=Vector3.zero;Physics.SyncTransforms();}
        [UnityTest]public IEnumerator CommonEnemyTimeToKill(){yield return TimeToKill(false);}
        [UnityTest]public IEnumerator BigBotTimeToKill(){yield return TimeToKill(true);}
        [UnityTest]public IEnumerator CapsulesCommonTimeToKill(){yield return TimeToKill(false);}
        [UnityTest]public IEnumerator CapsulesBigBotTimeToKill(){yield return TimeToKill(true);}
        [UnityTest]public IEnumerator CapsulesMountAndAutomatic(){yield return MountAndPresentation();}
        [UnityTest]public IEnumerator IntegratedMount(){yield return MountAndPresentation();}
        IEnumerator TimeToKill(bool big)
        {
            var target=Object.FindObjectsByType<EnemyController>().Single(e=>big?e.GetComponent<BigBotCombat>()!=null:e.GetComponent<RobotDamageProgression>()!=null);var hp=target.GetComponent<Health>();var box=target.GetComponent<Collider>();Physics.SyncTransforms();var center=box.bounds.center;Move(new Vector3(center.x,.03f,box.bounds.min.z-5));yield return new WaitForSeconds(.3f);var weapon=manager.GetActiveWeapon();var projectile=weapon.ProjectilePrefab.GetComponent<ProjectileStandard>();var times=new List<float>();int hits=0;float first=-1,death=-1;hp.OnDamaged+=(amount,source)=>{hits++;};hp.OnDie+=()=>death=Time.time;weapon.OnShoot+=()=>{times.Add(Time.time);if(first<0)first=Time.time;};string label=weapon.DelayBetweenShots<.3f?"after":"before";
            if(!big){ArmProfile(label);ScreenCapture.CaptureScreenshot(Reports+"/"+label+"-idle.png");}
            float deadline=Time.time+100,next=Time.time;if(weapon.ShootType==WeaponShootType.Automatic){InputSystem.QueueStateEvent(mouse,new MouseState{buttons=1});while(hp&&hp.CurrentHealth>0&&Time.time<deadline)yield return null;}else while(hp&&hp.CurrentHealth>0&&Time.time<deadline){if(Time.time>=next){InputSystem.QueueStateEvent(mouse,new MouseState{buttons=1});yield return null;InputSystem.QueueStateEvent(mouse,new MouseState());yield return null;next=times.Count>0?Mathf.Max(Time.time+.0001f,times[times.Count-1]+weapon.DelayBetweenShots+.001f):Time.time+.03f;}else yield return null;}
            InputSystem.QueueStateEvent(mouse,new MouseState());float min=times.Count>1?times.Zip(times.Skip(1),(a,b)=>b-a).Min():0;System.IO.File.WriteAllText(Reports+"/ttk-"+label+"-"+(big?"bigbot":"t07")+".json",JsonUtility.ToJson(new Measurement{enemy=target.name,health=hp.MaxHealth,interval=weapon.DelayBetweenShots,damage=projectile.Damage,dps=projectile.Damage/weapon.DelayBetweenShots,ammo=weapon.MaxAmmo,reload=weapon.AmmoReloadRate,reloadDelay=weapon.AmmoReloadDelay,shots=times.Count,hits=hits,ttk=death-first,minimumInterval=min,captureStep=Time.captureDeltaTime},true));Assert.That(death,Is.GreaterThan(first),"Enemy must die from real projectile hits");Assert.That(hits,Is.EqualTo(Mathf.CeilToInt(hp.MaxHealth/projectile.Damage)));Assert.That(min,Is.GreaterThanOrEqualTo(weapon.DelayBetweenShots-.0001f));
        }
        [System.Serializable]sealed class Measurement{public string enemy;public float health,interval,damage,dps,reload,reloadDelay,ttk,minimumInterval,captureStep;public int ammo,shots,hits;}
        void ArmProfile(string label)
        {
            var hands=player.GetComponent<ProtagonistHandsPresentation>();var r=hands.FpsRoot.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(v=>v.name=="Forearm_R_FPS");var hand=hands.FpsRoot.GetComponentsInChildren<Transform>(true).Single(t=>t.name=="Hand_R");var mesh=new Mesh();r.BakeMesh(mesh,false);var scale=r.transform.lossyScale;var frame=manager.GetActiveWeapon().WeaponMuzzle;var points=mesh.vertices.Select(v=>Quaternion.Inverse(frame.rotation)*(r.transform.TransformPoint(new Vector3(v.x/scale.x,v.y/scale.y,v.z/scale.z))-hand.position)).ToArray();float max=points.Max(v=>v.z);var end=points.Where(v=>v.z>max-.012f).ToArray();System.IO.File.WriteAllText(Reports+"/arm-"+label+".txt","wrist="+hand.position+" maxZ="+max+" width="+(end.Max(v=>v.x)-end.Min(v=>v.x))+" height="+(end.Max(v=>v.y)-end.Min(v=>v.y))+" x="+end.Min(v=>v.x)+","+end.Max(v=>v.x)+" y="+end.Min(v=>v.y)+","+end.Max(v=>v.y));Object.Destroy(mesh);
        }
        void Capture(Camera camera,string name,int width=1280,int height=720)
        {var rt=new RenderTexture(width,height,24);var tex=new Texture2D(width,height,TextureFormat.RGB24,false);var old=RenderTexture.active;camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,width,height),0,0);tex.Apply();System.IO.File.WriteAllBytes(Reports+"/"+name+".png",tex.EncodeToPNG());camera.targetTexture=null;RenderTexture.active=old;Object.Destroy(rt);Object.Destroy(tex);}
        [UnityTest]public IEnumerator MountAndPresentation()
        {
            Move(new Vector3(-14,.03f,-11));yield return new WaitForSeconds(.3f);var weapon=manager.GetActiveWeapon();var original=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/IronRequiem/Prefabs/Weapons/Weapon_IR_Pistol_CombatPolish.prefab").GetComponent<WeaponController>();var hands=player.GetComponent<ProtagonistHandsPresentation>();Assert.That(hands.CurrentRepresentation,Is.EqualTo(ProtagonistHandsPresentation.Representation.Pistol));Assert.That(hands.RightHandVisible,Is.False);Assert.That(hands.LeftHandVisible,Is.False);
            if(capsules){var cells=weapon.transform.Find("GunRoot/TemplateCapsules");Assert.That(cells,Is.Not.Null);Assert.That(cells.childCount,Is.EqualTo(4));Assert.That(cells.GetComponentsInChildren<ParticleSystem>(true).Length,Is.Zero);Assert.That(cells.GetComponentsInChildren<Light>(true).Length,Is.Zero);Assert.That(cells.GetComponentsInChildren<Collider>(true).Length,Is.Zero);Assert.That(weapon.DelayBetweenShots,Is.EqualTo(.1f));Assert.That(weapon.ProjectilePrefab.GetComponent<ProjectileStandard>().Damage,Is.EqualTo(5.5f));}
            var standard=weapon.ProjectilePrefab.GetComponent<ProjectileStandard>();var source=original.ProjectilePrefab.GetComponent<ProjectileStandard>();Assert.That(standard.Speed,Is.EqualTo(source.Speed));Assert.That(standard.Radius,Is.EqualTo(source.Radius));Assert.That(standard.MaxLifeTime,Is.EqualTo(source.MaxLifeTime));Assert.That(standard.ImpactVfx,Is.SameAs(source.ImpactVfx));Assert.That(standard.TrajectoryCorrectionDistance,Is.EqualTo(source.TrajectoryCorrectionDistance));Assert.That(weapon.ShootType,Is.EqualTo(capsules?WeaponShootType.Automatic:original.ShootType));Assert.That(weapon.RecoilForce,Is.EqualTo(original.RecoilForce));Assert.That(weapon.AimZoomRatio,Is.EqualTo(original.AimZoomRatio));Assert.That(weapon.AimOffset,Is.EqualTo(original.AimOffset));
            var visual=weapon.GetComponentsInChildren<Transform>(true).Single(t=>t.name=="PrimaryModuleVisual");var guide=visual.GetComponentsInChildren<Transform>().Single(t=>t.name=="Muzzle");var attachment=visual.GetComponentsInChildren<Transform>().Single(t=>t.name=="Attachment");var wrist=hands.FpsRoot.GetComponentsInChildren<Transform>(true).Single(t=>t.name=="Hand_R");var arm=hands.FpsRoot.GetComponentsInChildren<SkinnedMeshRenderer>().Single(r=>r.name=="Forearm_R_FPS");var forearm=hands.FpsRoot.GetComponentsInChildren<Transform>(true).Single(t=>t.name=="Forearm_R");float length=Vector3.Distance(wrist.position,forearm.position);var mesh=new Mesh();arm.BakeMesh(mesh,false);var scale=arm.transform.lossyScale;var initial=mesh.vertices;var projections=initial.Select(v=>Vector3.Dot(arm.transform.TransformPoint(new Vector3(v.x/scale.x,v.y/scale.y,v.z/scale.z))-forearm.position,weapon.WeaponMuzzle.forward)).ToArray();float min=projections.Min();var cap=Enumerable.Range(0,initial.Length).Where(i=>projections[i]<min+.014f).ToArray();int visibleCut=0,frames=0,shots=0;var phaseCuts=new List<string>();weapon.OnShoot+=()=>shots++;
            for(int phase=0;phase<5;phase++){
                // Idle, moving, ADS moving, one held semi-auto shot/recoil, ADS shot/recoil.
                InputSystem.QueueStateEvent(keyboard,new KeyboardState(phase==1||phase==2?Key.W:Key.None));InputSystem.QueueStateEvent(mouse,new MouseState{buttons=(ushort)(phase==2?2:phase==3?1:phase==4?3:0)});int before=shots,cutBefore=visibleCut;float end=Time.time+.6f;
                while(Time.time<end){yield return new WaitForEndOfFrame();frames++;Assert.That(Vector3.Distance(guide.position,weapon.WeaponMuzzle.position),Is.LessThan(.0001f));Assert.That(Vector3.Angle(guide.forward,weapon.WeaponMuzzle.forward),Is.LessThan(.1f));Assert.That(Vector3.Distance(wrist.position,attachment.position+weapon.WeaponMuzzle.forward*.003f),Is.LessThan(.002f));Assert.That(Vector3.Distance(forearm.position,wrist.position),Is.EqualTo(length).Within(.001f));Assert.That(hands.RightHandVisible,Is.False);arm.BakeMesh(mesh,false);var vertices=mesh.vertices;scale=arm.transform.lossyScale;foreach(int i in cap){var world=arm.transform.TransformPoint(new Vector3(vertices[i].x/scale.x,vertices[i].y/scale.y,vertices[i].z/scale.z));var view=manager.WeaponCamera.WorldToViewportPoint(world);if(view.z>manager.WeaponCamera.nearClipPlane&&view.x>=0&&view.x<=1&&view.y>=0&&view.y<=1)visibleCut++;}}
                phaseCuts.Add(phase+":"+(visibleCut-cutBefore));Capture(player.PlayerCamera,"mount-phase-"+phase);if(phase==3){if(capsules)Assert.That(shots-before,Is.InRange(4,7),"Holding fire uses template automatic cadence");else Assert.That(shots-before,Is.EqualTo(1),"Holding fire remains semi automatic");}InputSystem.QueueStateEvent(mouse,new MouseState());yield return null;yield return null;
            }
            System.IO.File.WriteAllLines(Reports+"/cut-by-phase.txt",phaseCuts);Assert.That(visibleCut,Is.Zero,"Right arm proximal cut outside FPS frame");InputSystem.QueueStateEvent(keyboard,new KeyboardState());InputSystem.QueueStateEvent(mouse,new MouseState());ArmProfile("after");
            var close=new GameObject("ModuleJointReview").AddComponent<Camera>();close.cullingMask=manager.WeaponCamera.cullingMask;close.clearFlags=CameraClearFlags.SolidColor;close.backgroundColor=new Color(.08f,.1f,.13f);close.nearClipPlane=.005f;close.fieldOfView=40;close.transform.position=attachment.position-weapon.WeaponMuzzle.forward*.32f+weapon.WeaponMuzzle.right*.32f+weapon.WeaponMuzzle.up*.12f;close.transform.LookAt(attachment.position+weapon.WeaponMuzzle.forward*.10f);Capture(close,"mount-joint-detail",1280,960);Object.Destroy(close.gameObject);Object.Destroy(mesh);
            System.IO.File.WriteAllText(Reports+"/mount-check.txt","frames="+frames+" cap vertices="+cap.Length+" visible proximal cut="+visibleCut+" forearm length="+length+" muzzle alignment and wrist connection checked every frame; firing mode verified");
            var prefab=weapon.SourcePrefab.GetComponent<WeaponController>();manager.RemoveWeapon(weapon);yield return new WaitForSeconds(1.3f);Assert.That(hands.RightHandVisible,Is.True,"Original hand available when module absent");Assert.That(manager.AddWeapon(prefab),Is.True);manager.SwitchToWeaponIndex(0,true);yield return new WaitForSeconds(2.1f);Assert.That(hands.RightHandVisible,Is.False);Assert.That(hands.CurrentRepresentation,Is.EqualTo(ProtagonistHandsPresentation.Representation.Pistol));
        }
